.ds {
  --ds-bg:var(--p-bg,#ffffff);
  --ds-surface:var(--p-surface,#f1f3f6);
  --ds-high:var(--p-high,#fafbfc);
  --ds-text:var(--p-ink,#2c333d);
  --ds-muted:var(--p-muted,#59636f);
  --ds-border:var(--p-line,#c2cad5);
  --ds-control-border:var(--p-control-border,#7b8592);
  --ds-soft:var(--p-soft,#d3e8de);
  --ds-accent:var(--p-accent,#303b48);
  --ds-on-accent:var(--p-on-accent,#ffffff);
  --ds-focus:var(--p-highlight,#6153b5);
  --ds-error:var(--p-error,#a3313e);
  --ds-success:var(--p-success,#26614f);
  --ds-warning:var(--p-warning,#805719);
  --ds-radius:var(--p-radius,24px);
  --ds-control-radius:var(--p-control-radius,16px);
  --ds-shadow:var(--p-shadow,6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed);
  --ds-raised:var(--p-raised,3px 4px 8px #b9c3d066, -3px -3px 8px #ffffffed);
  --ds-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9);
  --ds-glass:var(--p-glass,#f6f8fbe8);
  --ds-disabled:var(--p-disabled,#dce1e8);
  --ds-duration:var(--p-duration,140ms);
  --ds-font:var(--p-font,Pretendard, sans-serif);
  --ds-display-font:var(--p-display-font,Outfit, Pretendard, sans-serif);
  --ds-text-sm:var(--p-text-sm,13px);
  --ds-text-md:var(--p-text-md,16px);
  --ds-text-lg:var(--p-text-lg,24px);
  --ds-space-2:var(--p-space-xs,8px);
  --ds-space-3:var(--p-space-sm,12px);
  --ds-space-4:var(--p-space-md,16px);
  --ds-space-6:var(--p-space-lg,24px);
  --ds-space-8:var(--p-space-xl,32px);
}
.ds {
  color:var(--ds-text); background:var(--ds-bg); font:var(--ds-text-md)/1.5 var(--ds-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--ds-focus); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--ds-text-sm); margin-top:var(--ds-space-3); min-height:20px; color:var(--ds-muted); }
.ds .ds-surface { border:1px solid var(--ds-border); border-radius:var(--ds-radius); background:var(--ds-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--ds-shadow); border-color:#ffffff; }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--ds-inset); background:var(--ds-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--ds-high); box-shadow:0 8px 24px #38465e12; }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--ds-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--ds-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds .ds-badge { display:inline-flex; align-items:center; width:fit-content; padding:4px 10px; border:1px solid var(--ds-border); border-radius:99px; background:var(--ds-soft); color:var(--ds-text); font-size:12px; line-height:1.5; font-weight:600; }
.ds .ds-badge[data-tone="success"] { background:#e5f2eb; border-color:#8fb8a5; color:var(--ds-success); }
.ds .ds-badge[data-tone="error"] { background:#f9e8e9; border-color:#d4a2a8; color:var(--ds-error); }
.ds .ds-badge[data-tone="warning"] { background:#f6efd9; border-color:#b9a16f; color:var(--ds-warning); }
/* looks: tone keeps the color, look changes the shape */
.ds .ds-badge[data-look="outline"] { background:transparent; border-color:currentColor; }
.ds .ds-badge[data-look="solid"] { background:var(--ds-accent); border-color:var(--ds-accent); color:var(--ds-on-accent); }
.ds .ds-badge[data-look="solid"][data-tone="success"] { background:var(--ds-success); border-color:var(--ds-success); }
.ds .ds-badge[data-look="solid"][data-tone="error"] { background:var(--ds-error); border-color:var(--ds-error); }
.ds .ds-badge[data-look="solid"][data-tone="warning"] { background:var(--ds-warning); border-color:var(--ds-warning); }
.ds .ds-badge[data-look="dot"] { gap:6px; background:var(--ds-bg); }
.ds .ds-badge[data-look="dot"]::before { content:''; width:8px; height:8px; border-radius:50%; background:currentColor; }
.ds .ds-badge[data-look="square"] { border-radius:6px; }
.ds .ds-badge[data-look="tag"] { padding-left:18px; border-color:transparent; border-radius:0 6px 6px 0; clip-path:polygon(10px 0,100% 0,100% 100%,10px 100%,0 50%); }
.ds .ds-badge[data-look="raised"] { background:var(--ds-bg); border-color:transparent; box-shadow:var(--ds-raised); }

/* One markup, eleven shapes. Selection never rests on color alone: each shape adds a mark, a tile, a pill, a press or weight. */
/* Floating shapes declare --ds-nav-inset so a screen frame can keep them off the edges. */
.ds .ds-bottom-nav { position:relative; isolation:isolate; display:flex; justify-content:space-around; align-items:center; gap:4px; padding:6px; background:var(--ds-surface); border-top:1px solid var(--ds-border); }
.ds .ds-bottom-nav > :not(.ds-bottom-nav-create) { position:relative; display:flex; flex:1; min-width:44px; min-height:64px; flex-direction:column; justify-content:center; align-items:center; gap:5px; padding:6px; border:0; color:var(--ds-muted); background:transparent; font-size:12px; text-decoration:none; }
.ds .ds-bottom-nav > :is([aria-pressed="true"],[aria-current="page"]) { color:var(--ds-text); font-weight:750; }
.ds .ds-bottom-nav > :not(.ds-bottom-nav-create)::before,.ds .ds-bottom-nav > :not(.ds-bottom-nav-create)::after { content:''; position:absolute; pointer-events:none; }
.ds .ds-bottom-nav > .ds-bottom-nav-create { display:grid; place-items:center; flex:none; width:48px; height:48px; padding:0; border:0; border-radius:50%; color:var(--ds-on-accent); background:var(--ds-accent); box-shadow:var(--ds-raised); }
.ds .ds-bottom-nav > .ds-bottom-nav-create .ui-icon { width:24px; height:24px; stroke-width:2.2; }
/* 09 line: top bar (also the look without a variant) */
.ds .ds-bottom-nav:is(:not([data-variant]),[data-variant="line"]) > :is([aria-pressed="true"],[aria-current="page"])::before { top:-6px; left:18%; right:18%; height:3px; border-radius:0 0 3px 3px; background:var(--ds-accent); }
/* 01 minimal: flat, dot under the label */
.ds .ds-bottom-nav[data-variant="minimal"] { background:var(--ds-bg); border-top-color:transparent; }
.ds .ds-bottom-nav[data-variant="minimal"] > :is([aria-pressed="true"],[aria-current="page"])::after { bottom:2px; width:5px; height:5px; border-radius:50%; background:var(--ds-accent); }
/* 02 glass: translucent edge bar over the screen, light tile on the chosen item */
.ds .ds-bottom-nav[data-variant="glass"] { background:var(--ds-high); border-top-color:var(--ds-border); }
@supports(backdrop-filter:blur(16px)) { .ds .ds-bottom-nav[data-variant="glass"] { background:color-mix(in oklab, var(--ds-glass) 62%, transparent); backdrop-filter:blur(16px) saturate(1.4); } }
.ds .ds-bottom-nav[data-variant="glass"] > :not(.ds-bottom-nav-create) { border-radius:16px; }
.ds .ds-bottom-nav[data-variant="glass"] > :is([aria-pressed="true"],[aria-current="page"]) { background:color-mix(in oklab, var(--ds-high) 80%, transparent); box-shadow:inset 0 0 0 1px var(--ds-border); }
/* 03 float: floating capsule, create button inside, soft disc behind the chosen icon */
.ds .ds-bottom-nav[data-variant="float"] { --ds-nav-inset:var(--ds-space-3); padding:6px 8px; border:1px solid var(--ds-border); border-radius:999px; background:var(--ds-high); box-shadow:var(--ds-shadow); }
.ds .ds-bottom-nav[data-variant="float"] > :not(.ds-bottom-nav-create) { min-height:56px; }
.ds .ds-bottom-nav[data-variant="float"] > :is([aria-pressed="true"],[aria-current="page"])::before { top:4px; left:50%; width:36px; height:30px; margin-left:-18px; border-radius:15px; background:var(--ds-soft); z-index:-1; }
/* 04 neumorph: raised soft slab, chosen item pressed in */
.ds .ds-bottom-nav[data-variant="neumorph"] { --ds-nav-inset:var(--ds-space-3); padding:8px; border:0; border-radius:var(--ds-radius); background:var(--ds-surface); box-shadow:var(--ds-shadow); }
.ds .ds-bottom-nav[data-variant="neumorph"] > :not(.ds-bottom-nav-create) { border-radius:18px; }
.ds .ds-bottom-nav[data-variant="neumorph"] > :is([aria-pressed="true"],[aria-current="page"]) { background:var(--ds-surface); box-shadow:var(--ds-inset); }
/* 05 pill: only the chosen item shows its name, inside a soft pill */
.ds .ds-bottom-nav[data-variant="pill"] { padding:10px 8px; background:var(--ds-bg); }
.ds .ds-bottom-nav[data-variant="pill"] > :not(.ds-bottom-nav-create) { min-height:44px; flex-direction:row; gap:6px; border-radius:999px; }
.ds .ds-bottom-nav[data-variant="pill"] > :not([aria-pressed="true"],[aria-current="page"]) > span { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
.ds .ds-bottom-nav[data-variant="pill"] > :is([aria-pressed="true"],[aria-current="page"]) { flex:1.8; padding:6px 14px; background:var(--ds-soft); font-size:13px; }
/* 06 fab: edge bar with a notch, large create button rising out of it */
.ds .ds-bottom-nav[data-variant="fab"] { padding:6px 6px 6px; border-top:0; background:transparent; }
.ds .ds-bottom-nav[data-variant="fab"]::before { content:''; position:absolute; inset:0; z-index:-1; background:var(--ds-surface); border-top:1px solid var(--ds-border); -webkit-mask:radial-gradient(circle 37px at 50% 0, transparent 36px, black 37px); mask:radial-gradient(circle 37px at 50% 0, transparent 36px, black 37px); }
.ds .ds-bottom-nav[data-variant="fab"] > .ds-bottom-nav-create { width:60px; height:60px; margin-top:-56px; box-shadow:var(--ds-shadow); }
.ds .ds-bottom-nav[data-variant="fab"] > :is([aria-pressed="true"],[aria-current="page"])::before { top:4px; width:16px; height:3px; border-radius:2px; background:var(--ds-accent); }
/* 07 gradient: dark floating slab, light icons, soft chip on the chosen item */
.ds .ds-bottom-nav[data-variant="gradient"] { --ds-nav-inset:var(--ds-space-3); padding:8px; border:0; border-radius:var(--ds-radius); background:linear-gradient(135deg, var(--ds-accent), color-mix(in oklab, var(--ds-accent) 60%, var(--ds-success))); box-shadow:var(--ds-shadow); }
.ds .ds-bottom-nav:is([data-variant="gradient"],[data-variant="curve"]) > :not(.ds-bottom-nav-create) { color:color-mix(in oklab, var(--ds-on-accent) 74%, transparent); border-radius:16px; }
.ds .ds-bottom-nav:is([data-variant="gradient"],[data-variant="curve"]) > :is([aria-pressed="true"],[aria-current="page"]) { color:var(--ds-on-accent); }
.ds .ds-bottom-nav:is([data-variant="gradient"],[data-variant="curve"]) :focus-visible { outline-color:var(--ds-on-accent); }
.ds .ds-bottom-nav[data-variant="gradient"] > :is([aria-pressed="true"],[aria-current="page"]) { background:color-mix(in oklab, var(--ds-on-accent) 16%, transparent); box-shadow:inset 0 0 0 1px color-mix(in oklab, var(--ds-on-accent) 22%, transparent); }
/* 08 outline: thin line icons, short underline under the chosen label */
.ds .ds-bottom-nav[data-variant="outline"] { background:var(--ds-bg); }
.ds .ds-bottom-nav[data-variant="outline"] .ui-icon { stroke-width:1.25; }
.ds .ds-bottom-nav[data-variant="outline"] > :is([aria-pressed="true"],[aria-current="page"]) .ui-icon { stroke-width:2; }
.ds .ds-bottom-nav[data-variant="outline"] > :is([aria-pressed="true"],[aria-current="page"])::after { bottom:4px; width:18px; height:2px; border-radius:1px; background:var(--ds-text); }
/* 10 curve: a floating dark bar, rounded on every corner; a groove is cut above the chosen item and its icon rides in a dark disc inside the groove.
   The gap ring between disc and groove shows the screen behind, so the groove reads at a glance.
   Floating off the screen edges and a side padding wider than the corner radius keep the groove clear of the corners. --i is the chosen position, --n the item count, --pad the side padding. */
.ds .ds-bottom-nav[data-variant="curve"] { --ds-nav-inset:var(--ds-space-3); --i:0; --n:4; --pad:20px; padding:22px var(--pad) 8px; border:0; background:transparent; }
.ds .ds-bottom-nav[data-variant="curve"]::before { content:''; position:absolute; inset:0; z-index:-1; --x:calc(var(--pad) + (100% - 2 * var(--pad)) * (2 * var(--i) + 1) / (2 * var(--n))); border-radius:20px; background:var(--ds-accent); -webkit-mask:radial-gradient(circle 29px at var(--x) 0, transparent 28px, black 29px); mask:radial-gradient(circle 29px at var(--x) 0, transparent 28px, black 29px); }
.ds .ds-bottom-nav[data-variant="curve"]:has(> :nth-child(2):is([aria-pressed="true"],[aria-current="page"])) { --i:1; }
.ds .ds-bottom-nav[data-variant="curve"]:has(> :nth-child(3):is([aria-pressed="true"],[aria-current="page"])) { --i:2; }
.ds .ds-bottom-nav[data-variant="curve"]:has(> :nth-child(4):is([aria-pressed="true"],[aria-current="page"])) { --i:3; }
.ds .ds-bottom-nav[data-variant="curve"]:has(> :nth-child(5):is([aria-pressed="true"],[aria-current="page"])) { --i:4; }
.ds .ds-bottom-nav[data-variant="curve"]:has(> :last-child:nth-child(3)) { --n:3; }
.ds .ds-bottom-nav[data-variant="curve"]:has(> :last-child:nth-child(5)) { --n:5; }
.ds .ds-bottom-nav[data-variant="curve"] > :is([aria-pressed="true"],[aria-current="page"]) { justify-content:flex-end; }
.ds .ds-bottom-nav[data-variant="curve"] > :is([aria-pressed="true"],[aria-current="page"]) .ui-icon { position:absolute; top:-22px; left:50%; translate:-50% -50%; box-sizing:content-box; padding:12px; border-radius:50%; color:var(--ds-on-accent); background:var(--ds-accent); box-shadow:0 8px 16px -8px color-mix(in oklab, var(--ds-accent) 70%, transparent); }
/* 11 dock: floating rounded dock, chosen item is a filled tile */
.ds .ds-bottom-nav[data-variant="dock"] { --ds-nav-inset:var(--ds-space-3); border:1px solid var(--ds-border); border-radius:24px; box-shadow:var(--ds-shadow); padding:8px; background:var(--ds-high); }
.ds .ds-bottom-nav[data-variant="dock"] > :not(.ds-bottom-nav-create) { border-radius:17px; }
.ds .ds-bottom-nav[data-variant="dock"] > :is([aria-pressed="true"],[aria-current="page"]) { background:var(--ds-accent); color:var(--ds-on-accent); }
@supports(backdrop-filter:blur(16px)) { .ds .ds-bottom-nav[data-variant="dock"] { background:var(--ds-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-bottom-nav:is([data-variant="dock"],[data-variant="glass"]) { background:var(--ds-high); backdrop-filter:none; } }

.ds .ds-page { max-width:1080px; margin-inline:auto; }
.ds .ds-page-header { display:flex; justify-content:space-between; align-items:center; gap:16px; margin-bottom:var(--ds-space-8); }
.ds .ds-page-header h2 { font-size:32px; font-weight:650; letter-spacing:-.04em; margin-top:var(--ds-space-2); }
.ds .ds-eyebrow { font-size:var(--ds-text-sm); color:var(--ds-muted); }
.ds .ds-page > .ds-bottom-nav { margin:var(--ds-space-8) auto 0; max-width:480px; }
/* Looks: how the screen opens. Each look also brings its own bottom bar shape from the markup. */
.ds .ds-page[data-look="hero"] .ds-page-header { align-items:flex-end; padding:28px 20px 20px; border-radius:var(--ds-radius); background:var(--ds-soft); }
.ds .ds-page[data-look="hero"] .ds-page-header h2 { font-size:40px; line-height:1.1; }
.ds .ds-page[data-look="appbar"] .ds-page-header { position:relative; justify-content:center; padding:4px 64px 16px; margin-bottom:var(--ds-space-6); border-bottom:1px solid var(--ds-border); text-align:center; }
.ds .ds-page[data-look="appbar"] .ds-page-header h2 { margin-top:0; font-size:20px; letter-spacing:-.02em; }
.ds .ds-page[data-look="appbar"] .ds-page-header > .ds-badge { position:absolute; right:0; top:50%; translate:0 -60%; }
.ds .ds-page[data-look="sheet"] .ds-page-header { align-items:flex-start; margin-bottom:0; padding:24px 20px 64px; border-radius:var(--ds-radius) var(--ds-radius) 0 0; background:var(--ds-accent); color:var(--ds-on-accent); }
.ds .ds-page[data-look="sheet"] .ds-page-header .ds-eyebrow { color:color-mix(in oklab, var(--ds-on-accent) 74%, transparent); }
.ds .ds-page[data-look="sheet"] .ds-page-header + * { position:relative; margin-top:-32px; padding:24px 20px; border-radius:24px 24px 0 0; background:var(--ds-high); }
.ds .ds-page[data-look="magazine"] .ds-page-header { align-items:flex-end; padding-bottom:16px; border-bottom:2px solid var(--ds-text); }
.ds .ds-page[data-look="magazine"] .ds-page-header h2 { font:700 48px/1.05 var(--ds-display-font); letter-spacing:-.05em; }
.ds .ds-page[data-look="dashboard"] .ds-page-header { margin-bottom:var(--ds-space-4); }
.ds .ds-page-stats { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; margin:0 0 var(--ds-space-6); padding:0; list-style:none; }
.ds .ds-page-stats li { display:grid; gap:2px; padding:12px; border:1px solid var(--ds-border); border-radius:16px; background:var(--ds-surface); }
.ds .ds-page-stats strong { font:700 22px/1.2 var(--ds-display-font); letter-spacing:-.03em; }
.ds .ds-page-stats span { font-size:12px; color:var(--ds-muted); }
.ds .ds-template-slot { min-height:160px; display:grid; place-items:center; padding:var(--ds-space-6); border:1px dashed var(--ds-control-border); border-radius:var(--ds-radius); color:var(--ds-muted); font-size:14px; }

(function mountParts(root) {
  root.querySelectorAll('[data-indeterminate]').forEach(input => {
    if (!input.__pattoveInitialized) { input.indeterminate = true; input.__pattoveInitialized = true; }
  });
  if (root.__pattovePartsMounted) return;
  root.__pattovePartsMounted = true;
  function selectTab(tab) {
    const tabs = tab.closest('.ds-tabs');
    tabs.querySelectorAll('[role="tab"]').forEach(item => {
      const active = item === tab;
      item.setAttribute('aria-selected', String(active)); item.tabIndex = active ? 0 : -1;
      tabs.querySelector('#' + CSS.escape(item.getAttribute('aria-controls'))).hidden = !active;
    });
    tabs.dispatchEvent(new CustomEvent('pattove:tabchange', { bubbles: true, detail: { label: tab.textContent.trim(), panel: tab.getAttribute('aria-controls') } }));
  }
  function filter(form) {
    const module = form.closest('.ds-search-module');
    const query = form.elements.query.value.trim().toLocaleLowerCase();
    const status = form.elements.status.value;
    let count = 0;
    module.querySelectorAll('[data-result]').forEach(item => {
      const match = query.split(/\s+/).every(term => item.dataset.result.toLocaleLowerCase().includes(term)) && (status === 'all' || item.dataset.resultStatus === status);
      item.hidden = !match; if (match) count++;
    });
    module.querySelector('.ds-result-count').textContent = count + '개의 컬렉션';
    module.querySelector('.ds-empty').hidden = count > 0;
    module.querySelector('.ds-demo-note').textContent = '';
  }
  root.addEventListener('submit', event => {
    if (!event.target.matches('[data-part-search]')) return;
    event.preventDefault(); filter(event.target);
  });
  root.addEventListener('change', event => {
    // The status filter is a select, or a radio chip group in the chips look.
    if (event.target.matches('[data-part-search] [name="status"]')) filter(event.target.form);
  });
  root.addEventListener('click', event => {
    const tab = event.target.closest('.ds-tab');
    if (tab) selectTab(tab);
    const button = event.target.closest('[data-part-action]');
    if (!button || button.disabled) return;
    const action = button.dataset.partAction;
    if (['open-record', 'close-record', 'save-record'].includes(action)) {
      const module = button.closest('.ds-search-module');
      const detail = module.querySelector('.ds-record-detail');
      if (action === 'save-record') {
        button.setAttribute('aria-pressed', String(button.getAttribute('aria-pressed') !== 'true'));
        module.__recordOpener.dataset.saved = button.getAttribute('aria-pressed');
        module.__recordOpener.setAttribute('aria-label', module.querySelector('.ds-record-detail h3').textContent + (button.getAttribute('aria-pressed') === 'true' ? ', 보관됨, 상세 열기' : ', 상세 열기'));
        module.querySelector('.ds-demo-note').textContent = button.getAttribute('aria-pressed') === 'true' ? '이 화면에서 컬렉션에 보관했어요.' : '보관을 해제했어요.';
        const record = module.__recordOpener.closest('[data-result]');
        module.dispatchEvent(new CustomEvent('pattove:save', { bubbles: true, detail: {
          id: record.dataset.recordId,
          title: detail.querySelector('h3').textContent,
          description: detail.querySelector('p').textContent,
          tag: record.dataset.resultStatus,
          saved: button.getAttribute('aria-pressed') === 'true'
        } }));
        return;
      }
      const open = action === 'open-record';
      if (open) {
        module.__recordOpener = button;
        const card = button.closest('.ds-card');
        detail.querySelector('h3').textContent = card.querySelector('h3').textContent;
        detail.querySelector('p').textContent = card.querySelector('.ds-card-body > p').textContent;
        detail.querySelector('[data-part-action="save-record"]').setAttribute('aria-pressed', button.dataset.saved || 'false');
      }
      module.querySelectorAll(':scope > form, :scope > .ds-result-count, :scope > .ds-results').forEach(element => { element.hidden = open; });
      detail.hidden = !open;
      module.querySelector('.ds-demo-note').textContent = '';
      if (open) detail.focus(); else module.__recordOpener?.focus();
    } else if (action === 'notify') {
      button.closest('.ds-feedback-example').querySelector('[data-part-feedback]').hidden = false;
    } else if (action === 'nav') {
      const items = [...button.closest('nav').querySelectorAll(':scope > [data-part-action="nav"]')];
      items.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
      button.dispatchEvent(new CustomEvent('pattove:navigate', { bubbles: true, detail: { index: items.indexOf(button), label: button.textContent.trim() } }));
    } else if (action === 'create') {
      button.dispatchEvent(new CustomEvent('pattove:create', { bubbles: true }));
    } else if (action === 'select-card') {
      const card = button.closest('.ds-card');
      const selected = card.dataset.selected !== 'true';
      card.dataset.selected = String(selected);
      button.setAttribute('aria-pressed', String(selected));
      button.lastChild.textContent = selected ? '선택됨' : '선택하기';
      card.dispatchEvent(new CustomEvent('pattove:select', { bubbles: true, detail: { selected, title: card.querySelector('h3').textContent } }));
    } else if (action === 'reset-search') {
      const form = button.closest('.ds-search-module').querySelector('form');
      form.reset(); filter(form); form.elements.query.focus();
    } else if (action === 'press') {
      button.dispatchEvent(new CustomEvent('pattove:action', { bubbles: true, detail: { label: button.getAttribute('aria-label') || button.textContent.trim() } }));
      const region = button.closest('.ds-search-module, .part-demo, .specimen') || root;
      const output = region.querySelector('.ds-demo-note');
      if (output) {
        const card = button.closest('.ds-card');
        output.textContent = card ? card.querySelector('h3').textContent + ' 선택됨' : (button.getAttribute('aria-label') || button.textContent.trim()) + ' 버튼을 눌렀어요.';
      }
    }
  });
  root.addEventListener('keydown', event => {
    const tab = event.target.closest('.ds-tab');
    if (!tab) return;
    const list = tab.closest('[role="tablist"]');
    // A vertical tab list moves with the up and down arrows, a horizontal one with left and right.
    const [back, forward] = list.getAttribute('aria-orientation') === 'vertical' ? ['ArrowUp', 'ArrowDown'] : ['ArrowLeft', 'ArrowRight'];
    if (![back, forward, 'Home', 'End'].includes(event.key)) return;
    event.preventDefault();
    const tabs = [...list.querySelectorAll('.ds-tab')];
    const current = tabs.indexOf(tab);
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (current + (event.key === forward ? 1 : -1) + tabs.length) % tabs.length;
    selectTab(tabs[next]); tabs[next].focus();
  });
})(document);

